#!/usr/bin/env python3
"""Add buffer-aware, direction-aware Reel scheduling to the 4.37 controller."""
from pathlib import Path

OLD_NETWORK="""var fastNetwork=networkOnline&&networkValidated&&!networkMetered&&!powerSaving&&!conservative&&!/^(slow-)?2g$/.test(networkType),releaseDelay=1100;"""
NEW_NETWORK="""var fastNetwork=networkOnline&&networkValidated&&!networkMetered&&!powerSaving&&!conservative&&!/^(slow-)?2g$/.test(networkType),releaseDelay=1700;"""

OLD_STATE="""var st={card:card,v:v,source:source,position:0,userPaused:false,waitTimer:0,releaseTimer:0,playToken:0,playPending:false,stallTimer:0,lastProgressTime:0,recoveryCount:0,lastRecoveryAt:0,recovering:false};"""
NEW_STATE="""var st={card:card,v:v,source:source,position:0,userPaused:false,waitTimer:0,releaseTimer:0,playToken:0,playPending:false,stallTimer:0,lastProgressTime:0,lastObservedTime:0,recoveryCount:0,lastRecoveryAt:0,recovering:false,softRecoveryCount:0,seeking:false,firstFrame:false};"""

OLD_RELEASE="""function release(st){if(!st)return;cancelRelease(st);clearStall(st);st.playToken++;st.playPending=false;st.v.pause();clearTimeout(st.waitTimer);st.card.removeAttribute('data-mm46-loading');if(st.v.hasAttribute('src')){st.position=Number.isFinite(st.v.currentTime)?st.v.currentTime:0;st.v.removeAttribute('src');st.v.load();}delete st.v.dataset.mm46Attached;}"""
NEW_RELEASE="""function release(st){if(!st)return;cancelRelease(st);clearStall(st);st.playToken++;st.playPending=false;st.v.pause();clearTimeout(st.waitTimer);st.firstFrame=false;st.softRecoveryCount=0;st.lastObservedTime=0;st.card.removeAttribute('data-mm46-loading');st.card.removeAttribute('data-mm438-primed');if(st.v.hasAttribute('src')){st.position=Number.isFinite(st.v.currentTime)?st.v.currentTime:0;st.v.removeAttribute('src');st.v.load();}delete st.v.dataset.mm46Attached;}"""

OLD_BUDGET="""function budget(){var i=cards.indexOf(active),constrained=conservative||powerSaving||networkMetered||!networkValidated,keepAhead=pressure>=10||powerSaving?0:(fastNetwork&&memoryGb>=4?2:1);cards.forEach(function(c,n){var st=states.get(c);if(!st)return;if(i<0){scheduleRelease(st,300);return;}if(!networkOnline||!networkValidated){if(c===active)attach(st,'metadata','low');else scheduleRelease(st,200);return;}if(!isReels()||suspended||document.hidden){if(c===active){st.v.pause();attach(st,'metadata','low');}else scheduleRelease(st,300);return;}var distance=n-i;if(distance===0)attach(st,'auto','high');else if(distance===1)attach(st,constrained?'metadata':'auto',constrained?'low':'high');else if(distance===-1)attach(st,'metadata','low');else if(distance>1&&distance<=keepAhead)attach(st,'metadata','low');else scheduleRelease(st,releaseDelay);});}"""
NEW_BUDGET="""var budgetTimer=0;
function bufferedAhead(st){if(!st||!Number.isFinite(st.v.currentTime))return 0;var t=st.v.currentTime,b=st.v.buffered;try{for(var i=0;i<b.length;i++){if(t+.08>=b.start(i)&&t<=b.end(i)+.08)return Math.max(0,b.end(i)-t);}}catch(ignore){}return 0;}
function scheduleBudget(delay){clearTimeout(budgetTimer);budgetTimer=setTimeout(function(){budgetTimer=0;budget();},Math.max(0,delay||0));}
function activeBufferReady(){var st=active&&states.get(active);if(!st)return false;var reserve=conservative||networkMetered||powerSaving?1.25:2.5;return st.firstFrame&&(bufferedAhead(st)>=reserve||st.v.readyState>=4);}
function budget(){var i=cards.indexOf(active),constrained=conservative||powerSaving||networkMetered||!networkValidated,keepAhead=pressure>=10||powerSaving?0:(fastNetwork&&memoryGb>=4?2:1),primary=scrollDirection>=0?1:-1,activeSafe=activeBufferReady();cards.forEach(function(c,n){var st=states.get(c);if(!st)return;c.removeAttribute('data-mm438-primed');if(i<0){scheduleRelease(st,300);return;}if(!networkOnline||!networkValidated){if(c===active)attach(st,'metadata','low');else scheduleRelease(st,200);return;}if(!isReels()||suspended||document.hidden){if(c===active){st.v.pause();attach(st,'metadata','low');}else scheduleRelease(st,300);return;}var distance=n-i;if(distance===0)attach(st,'auto','high');else if(distance===primary){if(constrained||!activeSafe)attach(st,'metadata','low');else{c.dataset.mm438Primed='1';attach(st,'auto','high');}}else if(distance===-primary&&pressure<10)attach(st,'metadata','low');else if(Math.abs(distance)>1&&Math.abs(distance)<=keepAhead)attach(st,'metadata','low');else scheduleRelease(st,releaseDelay);});}"""

OLD_CLEAR="""function clearStall(st){if(!st)return;clearTimeout(st.stallTimer);st.stallTimer=0;st.recovering=false;st.card.removeAttribute('data-mm437-recovering');st.card.removeAttribute('data-mm437-slow');}"""
NEW_CLEAR="""function clearStall(st){if(!st)return;clearTimeout(st.stallTimer);st.stallTimer=0;st.recovering=false;st.card.removeAttribute('data-mm437-recovering');st.card.removeAttribute('data-mm437-slow');st.card.removeAttribute('data-mm438-soft');st.card.removeAttribute('data-mm438-buffering');st.card.removeAttribute('data-mm438-slow');}"""

OLD_RECOVER="""function recoverStall(st){if(!st||active!==st.card||st.v.paused||blocked()||!networkOnline||!networkValidated)return;var now=Date.now();clearStall(st);if(st.recoveryCount>=2||now-st.lastRecoveryAt<18000){st.card.dataset.mm437Slow='1';return;}st.recoveryCount++;st.lastRecoveryAt=now;st.userPaused=false;st.position=Number.isFinite(st.v.currentTime)?st.v.currentTime:0;st.playToken++;st.playPending=false;st.recovering=true;st.card.dataset.mm437Recovering='1';attach(st,'auto','high');var token=st.playToken;var resume=function(){if(token!==st.playToken||active!==st.card||blocked()||!networkOnline||!networkValidated)return;clearStall(st);start(st,true);};st.v.addEventListener('loadedmetadata',resume,{once:true});try{st.v.pause();st.v.load();}catch(ignore){clearStall(st);st.card.dataset.mm437Slow='1';return;}st.stallTimer=setTimeout(function(){st.stallTimer=0;if(st.recovering){st.recovering=false;st.card.removeAttribute('data-mm437-recovering');st.card.dataset.mm437Slow='1';}},8000);}"""
NEW_RECOVER="""function recoverStall(st){if(!st||active!==st.card||st.v.paused||blocked()||!networkOnline||!networkValidated||st.seeking)return;var now=Date.now(),ahead=bufferedAhead(st);clearStall(st);if(Number.isFinite(st.v.duration)&&st.v.duration>0&&st.v.currentTime>=st.v.duration-.35){try{st.v.currentTime=0;}catch(ignore){}start(st,true);return;}if((ahead>.75||st.v.readyState>=3)&&st.softRecoveryCount<1){st.softRecoveryCount++;st.card.dataset.mm438Soft='1';st.playPending=false;var softToken=++st.playToken,soft=st.v.play();if(soft&&typeof soft.catch==='function')soft.catch(function(){});st.stallTimer=setTimeout(function(){st.stallTimer=0;if(softToken!==st.playToken||active!==st.card||st.v.paused||blocked())return;recoverStall(st);},1500);return;}if(st.recoveryCount>=2||now-st.lastRecoveryAt<18000){st.card.dataset.mm437Slow='1';st.card.dataset.mm438Slow='1';return;}st.recoveryCount++;st.lastRecoveryAt=now;st.softRecoveryCount=0;st.userPaused=false;st.position=Number.isFinite(st.v.currentTime)?st.v.currentTime:0;st.firstFrame=false;st.playToken++;st.playPending=false;st.recovering=true;st.card.dataset.mm437Recovering='1';st.card.dataset.mm438Buffering='1';attach(st,'auto','high');var token=st.playToken;var resume=function(){if(token!==st.playToken||active!==st.card||blocked()||!networkOnline||!networkValidated)return;clearStall(st);start(st,true);};st.v.addEventListener('loadedmetadata',resume,{once:true});try{st.v.pause();st.v.load();}catch(ignore){clearStall(st);st.card.dataset.mm437Slow='1';st.card.dataset.mm438Slow='1';return;}st.stallTimer=setTimeout(function(){st.stallTimer=0;if(st.recovering){st.recovering=false;st.card.removeAttribute('data-mm437-recovering');st.card.dataset.mm437Slow='1';st.card.dataset.mm438Slow='1';}},8000);}"""

OLD_SCHEDULE="""function scheduleStall(st){if(!st||st.recovering)return;clearTimeout(st.stallTimer);var observed=Number.isFinite(st.v.currentTime)?st.v.currentTime:0;var delay=conservative||networkMetered||powerSaving?6500:4200;st.stallTimer=setTimeout(function(){st.stallTimer=0;if(active!==st.card||st.v.paused||blocked()||!networkOnline||!networkValidated)return;var current=Number.isFinite(st.v.currentTime)?st.v.currentTime:0;if(current>observed+.15)return;recoverStall(st);},delay);}"""
NEW_SCHEDULE="""function scheduleStall(st){if(!st||st.recovering||st.seeking)return;clearTimeout(st.stallTimer);var observed=Number.isFinite(st.v.currentTime)?st.v.currentTime:0,observedBuffer=bufferedAhead(st);var delay=conservative||networkMetered||powerSaving?6500:4200;st.stallTimer=setTimeout(function(){st.stallTimer=0;if(active!==st.card||st.v.paused||blocked()||!networkOnline||!networkValidated||st.seeking)return;var current=Number.isFinite(st.v.currentTime)?st.v.currentTime:0;if(current>observed+.15)return;if(bufferedAhead(st)>observedBuffer+1.5){scheduleStall(st);return;}recoverStall(st);},delay);}"""

OLD_START_MARK="""st.card.removeAttribute('data-mm437-slow');st.card.removeAttribute('data-mm437-recovering');st.playPending=true;"""
NEW_START_MARK="""st.card.removeAttribute('data-mm437-slow');st.card.removeAttribute('data-mm437-recovering');st.card.removeAttribute('data-mm438-soft');st.card.removeAttribute('data-mm438-buffering');st.card.removeAttribute('data-mm438-slow');st.playPending=true;"""

OLD_ACTIVATE="""function activate(card){if(!card||!states.has(card)||!isReels())return;if(active===card){budget();return;}pauseAll();if(active)active.removeAttribute('data-mm46-active');active=card;card.dataset.mm46Active='1';var st=states.get(card);budget();start(st,false);}"""
NEW_ACTIVATE="""function activate(card){if(!card||!states.has(card)||!isReels())return;if(active===card){budget();return;}var previousIndex=cards.indexOf(active),nextIndex=cards.indexOf(card);if(previousIndex>=0&&nextIndex>=0&&nextIndex!==previousIndex)scrollDirection=nextIndex>previousIndex?1:-1;pauseAll();if(active)active.removeAttribute('data-mm46-active');active=card;card.dataset.mm46Active='1';var st=states.get(card);budget();start(st,false);}"""

OLD_RETRY="""var retry=button('Coba putar ulang video','retry',function(e){e.stopPropagation();clearStall(st);st.recoveryCount=0;st.lastRecoveryAt=0;st.userPaused=false;v.load();start(st,true);},'mm46-retry');"""
NEW_RETRY="""var retry=button('Coba putar ulang video','retry',function(e){e.stopPropagation();clearStall(st);st.recoveryCount=0;st.softRecoveryCount=0;st.lastRecoveryAt=0;st.firstFrame=false;st.userPaused=false;v.load();start(st,true);},'mm46-retry');"""

OLD_PLAYING="""v.addEventListener('playing',function(){clearTimeout(st.waitTimer);clearStall(st);card.removeAttribute('data-mm46-loading');card.removeAttribute('data-mm433-slow');card.dataset.mm46Playing='1';if(typeof v.requestVideoFrameCallback==='function')v.requestVideoFrameCallback(function(){card.dataset.mm435Frame='1';});else card.dataset.mm435Frame='1';budget();});"""
NEW_PLAYING="""v.addEventListener('playing',function(){clearTimeout(st.waitTimer);clearStall(st);card.removeAttribute('data-mm46-loading');card.removeAttribute('data-mm433-slow');card.dataset.mm46Playing='1';var markFrame=function(){st.firstFrame=true;card.dataset.mm435Frame='1';scheduleBudget(0);};if(typeof v.requestVideoFrameCallback==='function')v.requestVideoFrameCallback(markFrame);else markFrame();});"""

OLD_PAUSE="""v.addEventListener('pause',function(){card.removeAttribute('data-mm46-playing');clearTimeout(st.waitTimer);card.removeAttribute('data-mm46-loading');if(!st.recovering)clearStall(st);});"""
NEW_PAUSE="""v.addEventListener('pause',function(){card.removeAttribute('data-mm46-playing');clearTimeout(st.waitTimer);card.removeAttribute('data-mm46-loading');if(!st.recovering)clearStall(st);scheduleBudget(80);});"""

OLD_WAITING="""v.addEventListener('waiting',function(){clearTimeout(st.waitTimer);st.waitTimer=setTimeout(function(){if(active===card&&!v.paused&&!blocked())card.dataset.mm46Loading='1';},240);scheduleStall(st);});
 v.addEventListener('stalled',function(){scheduleStall(st);});"""
NEW_WAITING="""v.addEventListener('waiting',function(){clearTimeout(st.waitTimer);card.dataset.mm438Buffering='1';st.waitTimer=setTimeout(function(){if(active===card&&!v.paused&&!blocked())card.dataset.mm46Loading='1';},240);scheduleStall(st);});
 v.addEventListener('stalled',function(){card.dataset.mm438Buffering='1';scheduleStall(st);});"""

OLD_METADATA="""v.addEventListener('loadedmetadata',function(){if(st.position>0&&Number.isFinite(v.duration)){v.currentTime=Math.min(st.position,Math.max(0,v.duration-.1));st.position=0;}seeker.disabled=!(v.duration>0&&Number.isFinite(v.duration));});"""
NEW_METADATA="""v.addEventListener('loadedmetadata',function(){if(st.position>0&&Number.isFinite(v.duration)){v.currentTime=Math.min(st.position,Math.max(0,v.duration-.1));st.position=0;}seeker.disabled=!(v.duration>0&&Number.isFinite(v.duration));scheduleBudget(80);});
 v.addEventListener('loadeddata',function(){card.removeAttribute('data-mm438-buffering');scheduleBudget(60);});
 v.addEventListener('canplay',function(){card.removeAttribute('data-mm438-buffering');scheduleBudget(60);});
 v.addEventListener('progress',function(){if(active===card)scheduleBudget(90);});
 v.addEventListener('seeking',function(){st.seeking=true;clearStall(st);});
 v.addEventListener('seeked',function(){st.seeking=false;st.lastObservedTime=Number.isFinite(v.currentTime)?v.currentTime:0;if(!v.paused)scheduleStall(st);});"""

OLD_TIMEUPDATE="""v.addEventListener('timeupdate',function(){clearStall(st);if(Number.isFinite(v.currentTime)&&v.currentTime>st.lastProgressTime+8){st.lastProgressTime=v.currentTime;st.recoveryCount=0;}if(active!==card||!Number.isFinite(v.duration)||v.duration<=0)return;seeker.value=String(Math.round(1000*v.currentTime/v.duration));seeker.setAttribute('aria-valuetext',Math.floor(v.currentTime)+' dari '+Math.floor(v.duration)+' detik');});"""
NEW_TIMEUPDATE="""v.addEventListener('timeupdate',function(){var current=Number.isFinite(v.currentTime)?v.currentTime:0;if(current+.5<st.lastObservedTime){st.lastObservedTime=current;st.lastProgressTime=current;st.recoveryCount=0;st.softRecoveryCount=0;}if(current>st.lastObservedTime+.25){st.lastObservedTime=current;st.softRecoveryCount=0;clearStall(st);}if(current>st.lastProgressTime+8){st.lastProgressTime=current;st.recoveryCount=0;}if(active!==card||!Number.isFinite(v.duration)||v.duration<=0)return;seeker.value=String(Math.round(1000*current/v.duration));seeker.setAttribute('aria-valuetext',Math.floor(current)+' dari '+Math.floor(v.duration)+' detik');});"""

OLD_ERROR="""v.addEventListener('error',function(){clearStall(st);if(v.hasAttribute('src')){card.dataset.mm46Error='1';card.dataset.mm437Slow='1';clearTimeout(st.waitTimer);card.removeAttribute('data-mm46-loading');}});"""
NEW_ERROR="""v.addEventListener('error',function(){clearStall(st);if(v.hasAttribute('src')){card.dataset.mm46Error='1';card.dataset.mm437Slow='1';card.dataset.mm438Slow='1';clearTimeout(st.waitTimer);card.removeAttribute('data-mm46-loading');}});"""

OLD_KEYS="""function keys(e){if(!isReels()||blocked()||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();var step=e.key==='ArrowDown'?1:-1;feed.scrollBy({top:step*feed.clientHeight,behavior:reduce.matches?'auto':'smooth'});}}"""
NEW_KEYS="""function keys(e){if(!isReels()||blocked()||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();var step=e.key==='ArrowDown'?1:-1;scrollDirection=step;scheduleBudget(0);feed.scrollBy({top:step*feed.clientHeight,behavior:reduce.matches?'auto':'smooth'});}}"""

OLD_SCROLL="""var scrollTimer=0;function scrollFallback(){if(intersection)return;clearTimeout(scrollTimer);scrollTimer=setTimeout(function(){if(cards.length)activate(cards[Math.max(0,Math.min(cards.length-1,Math.round(feed.scrollTop/feed.clientHeight)))]);},50);}"""
NEW_SCROLL="""var scrollTimer=0,lastScrollTop=feed.scrollTop||0,scrollDirection=1;function scrollFallback(){if(intersection)return;clearTimeout(scrollTimer);scrollTimer=setTimeout(function(){if(cards.length)activate(cards[Math.max(0,Math.min(cards.length-1,Math.round(feed.scrollTop/feed.clientHeight)))]);},50);}function scrollActivity(){var top=feed.scrollTop||0,delta=top-lastScrollTop;if(Math.abs(delta)>6){scrollDirection=delta>0?1:-1;lastScrollTop=top;scheduleBudget(40);}scrollFallback();}"""

OLD_FEED_EVENT="""feed.addEventListener('scroll',scrollFallback,{passive:true});"""
NEW_FEED_EVENT="""feed.addEventListener('scroll',scrollActivity,{passive:true});"""

OLD_DESTROY="""function destroy(){disposed=true;clearTimeout(resumeTimer);pauseAll();cards.forEach(function(c){release(states.get(c));});feedObserver.disconnect();modeObserver.disconnect();dialogObserver.disconnect();if(intersection)intersection.disconnect();clearTimeout(scrollTimer);window.removeEventListener('mm45:suspend',onSuspend);window.removeEventListener('mm45:resume',onResume);window.removeEventListener('mmapp:memory',memoryChanged);window.removeEventListener('mmapp:foreground',foregroundChanged);window.removeEventListener('mmapp:background',backgroundChanged);window.removeEventListener('mmapp:runtime',runtimeChanged);window.removeEventListener('mmapp:network',runtimeChanged);window.removeEventListener('mmapp:power',powerChanged);window.removeEventListener('online',networkChanged);window.removeEventListener('offline',networkChanged);window.removeEventListener('mm435:network',networkChanged);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',keys);window.removeEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.removeEventListener('resize',dimensions);if(conn&&conn.removeEventListener)conn.removeEventListener('change',connectionChanged);}"""
NEW_DESTROY="""function destroy(){disposed=true;clearTimeout(resumeTimer);clearTimeout(budgetTimer);pauseAll();cards.forEach(function(c){release(states.get(c));});feedObserver.disconnect();modeObserver.disconnect();dialogObserver.disconnect();if(intersection)intersection.disconnect();clearTimeout(scrollTimer);feed.removeEventListener('scroll',scrollActivity);window.removeEventListener('mm45:suspend',onSuspend);window.removeEventListener('mm45:resume',onResume);window.removeEventListener('mmapp:memory',memoryChanged);window.removeEventListener('mmapp:foreground',foregroundChanged);window.removeEventListener('mmapp:background',backgroundChanged);window.removeEventListener('mmapp:runtime',runtimeChanged);window.removeEventListener('mmapp:network',runtimeChanged);window.removeEventListener('mmapp:power',powerChanged);window.removeEventListener('online',networkChanged);window.removeEventListener('offline',networkChanged);window.removeEventListener('mm435:network',networkChanged);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',keys);window.removeEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.removeEventListener('resize',dimensions);if(conn&&conn.removeEventListener)conn.removeEventListener('change',connectionChanged);}"""

REPLACEMENTS=[
    (OLD_NETWORK,NEW_NETWORK),(OLD_STATE,NEW_STATE),(OLD_RELEASE,NEW_RELEASE),
    (OLD_BUDGET,NEW_BUDGET),(OLD_CLEAR,NEW_CLEAR),(OLD_RECOVER,NEW_RECOVER),
    (OLD_SCHEDULE,NEW_SCHEDULE),(OLD_START_MARK,NEW_START_MARK),(OLD_ACTIVATE,NEW_ACTIVATE),
    (OLD_RETRY,NEW_RETRY),(OLD_PLAYING,NEW_PLAYING),(OLD_PAUSE,NEW_PAUSE),
    (OLD_WAITING,NEW_WAITING),(OLD_METADATA,NEW_METADATA),(OLD_TIMEUPDATE,NEW_TIMEUPDATE),
    (OLD_ERROR,NEW_ERROR),(OLD_KEYS,NEW_KEYS),(OLD_SCROLL,NEW_SCROLL),
    (OLD_FEED_EVENT,NEW_FEED_EVENT),(OLD_DESTROY,NEW_DESTROY),
]

def patch_controller(path:Path)->None:
    text=path.read_text(encoding='utf-8')
    for old,new in REPLACEMENTS:
        count=text.count(old)
        assert count==1,f'{path}: expected one 4.37 anchor, found {count}: {old[:140]!r}'
        text=text.replace(old,new,1)
    path.write_text(text,encoding='utf-8')
